    std::istringstream iss(ip);
    std::string octet;
    uint32_t result = 0;
    int dot_count = 0;

    while (std::getline(iss, octet, '.')) {
        if (dot_count >= 3) break;
        int val = 0;
        std::istringstream octet_stream(octet);
        if (!(octet_stream >> val)) {
            throw std::invalid_argument("Invalid IP address format");
        }
        if (val < 0 || val > 255) {
            throw std::invalid_argument("Invalid IP octet value");
        }
        result = (result << 8) | val;
        dot_count++;
    }

    if (dot_count != 4) {
        throw std::invalid_argument("Invalid IP address format");
    }

    return result;
}

